-- User_F Core summon (server Script)
-- Put this Script inside a Model that contains a BasePart named "Core".
-- Clicking the Core makes the whole model rumble, rise, spin and tear itself apart,
-- then it explodes and User_F spawns where the model stood.
-- (Generated by build_oneline.py from User_F_Core.template.lua + User_F.lua.)

-- What it does: User_F is a horror NPC that chases the nearest player, says "LET ME IN" in
-- speech bubbles, climbs walls / crawls on ceilings, bangs on and breaks windows, and has 4 phases
-- (it ragdolls and gets back up 3 times). Everything below is plain, readable Luau: no require(),
-- no loadstring, no external assets except Roblox's default R6 animations and built-in sounds.

-- SETTINGS -------------------------------------------------------------------------------------
-- Effects that reach outside this model are OFF by default. Turn on only what you want in your game.
local KILL = true -- catching a player picks them up, shakes them and throws them into the ground (they respawn)
local SCREEN_EFFECTS = false -- "LET ME IN" spam and a jumpscare on the screens of nearby players
local LIGHTING_EFFECTS = false -- sky briefly turns red, nearby lights flicker
local BREAK_ANYTHING = false -- false: it only breaks/collapses parts named "Window"/"Glass"
--                              or parts with the attribute UserF_Breakable = true
-------------------------------------------------------------------------------------------------

local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local Debris = game:GetService("Debris")

local model = script.Parent
local core = model:FindFirstChild("Core", true)
assert(core and core:IsA("BasePart"), "User_F: no BasePart named 'Core' inside " .. model:GetFullName())

local RED = Color3.fromRGB(255, 0, 0)
local RISE_TIME = 1.5 -- rumbling on the ground
local SPIN_TIME = 4 -- rising, spinning, coming apart

local clicker = core:FindFirstChildOfClass("ClickDetector") or Instance.new("ClickDetector")
clicker.MaxActivationDistance = 32
clicker.Parent = core

-- Spawns User_F at SPAWN_AT (the body below is User_F.lua)
local function spawnUserF(SPAWN_AT)
	local P = game:GetService("Players")
	local RunS = game:GetService("RunService")
	local PFS = game:GetService("PathfindingService")
	local TS = game:GetService("TweenService")
	local L = game:GetService("Lighting")
	local D = game:GetService("Debris")
	local MSG = "LET ME IN"
	local old = workspace:FindFirstChild("User_F")
	if old then
		old:Destroy()
	end
	local WHITE = Color3.fromRGB(245, 245, 245)
	local GRAY = Color3.fromRGB(163, 162, 165)
	-- rig
	local hd = Instance.new("HumanoidDescription")
	hd.HeadColor = WHITE
	hd.LeftArmColor = WHITE
	hd.RightArmColor = WHITE
	hd.LeftLegColor = WHITE
	hd.RightLegColor = WHITE
	hd.TorsoColor = GRAY
	local rig = P:CreateHumanoidModelFromDescription(hd, Enum.HumanoidRigType.R6)
	rig.Name = "User_F"
	local hum = rig:FindFirstChildOfClass("Humanoid")
	local root = rig:WaitForChild("HumanoidRootPart")
	local head = rig:WaitForChild("Head")
	for _, v in ipairs(rig:GetDescendants()) do
		if v.Name == "Animate" or v:IsA("Accessory") or v:IsA("Clothing") or v:IsA("ShirtGraphic") then
			v:Destroy()
		elseif v:IsA("BasePart") and v ~= root then
			v.Color = v.Name == "Torso" and GRAY or WHITE
		end
	end
	local bc = rig:FindFirstChildOfClass("BodyColors")
	if bc then
		bc.HeadColor3 = WHITE
		bc.LeftArmColor3 = WHITE
		bc.RightArmColor3 = WHITE
		bc.LeftLegColor3 = WHITE
		bc.RightLegColor3 = WHITE
		bc.TorsoColor3 = GRAY
	end
	-- normal Roblox face
	if not head:FindFirstChildOfClass("Decal") then
		local fc = Instance.new("Decal")
		fc.Name = "face"
		fc.Texture = "rbxasset://textures/face.png"
		fc.Face = Enum.NormalId.Front
		fc.Parent = head
	end
	local glow = Instance.new("PointLight")
	glow.Color = Color3.new(1, 0, 0)
	glow.Brightness = 2
	glow.Range = 10
	glow.Parent = head
	hum.MaxHealth = 1000
	hum.Health = 1000
	hum.WalkSpeed = 16
	hum.BreakJointsOnDeath = false
	hum.HealthDisplayDistance = 0
	hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
	local phase, downed, dead, killing, crawling = 1, false, false, false, false
	local down
	local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
	-- helpers
	local function ang(x, y, z)
		return CFrame.Angles(math.rad(x), math.rad(y), math.rad(z))
	end
	local function alive(c)
		local h = c and c:FindFirstChildOfClass("Humanoid")
		if h and h.Health > 0 and c:FindFirstChild("HumanoidRootPart") then
			return h
		end
	end
	local function params()
		local rp = RaycastParams.new()
		rp.FilterType = Enum.RaycastFilterType.Exclude
		local ex = { rig }
		for _, p in ipairs(P:GetPlayers()) do
			if p.Character then
				table.insert(ex, p.Character)
			end
		end
		rp.FilterDescendantsInstances = ex
		return rp
	end
	local function nearest()
		local best, bd = nil, 1e9
		for _, p in ipairs(P:GetPlayers()) do
			if alive(p.Character) then
				local d = (p.Character.HumanoidRootPart.Position - root.Position).Magnitude
				if d < bd then
					best, bd = p, d
				end
			end
		end
		return best, bd
	end
	local function near(pos, r)
		local t = {}
		for _, p in ipairs(P:GetPlayers()) do
			if alive(p.Character) and (p.Character.HumanoidRootPart.Position - pos).Magnitude <= r then
				table.insert(t, p)
			end
		end
		return t
	end
	local function isChar(x)
		for _, p in ipairs(P:GetPlayers()) do
			if p.Character and x:IsDescendantOf(p.Character) then
				return true
			end
		end
		return x:IsDescendantOf(rig)
	end
	local function allowed(x)
		local n = x.Name:lower()
		return BREAK_ANYTHING
			or x:GetAttribute("UserF_Breakable") == true
			or n:find("window") ~= nil
			or n:find("glass") ~= nil
	end
	local function breakable(x)
		return x
			and x:IsA("BasePart")
			and not x:IsA("Terrain")
			and not x:IsA("SpawnLocation")
			and x.Name ~= "Baseplate"
			and x.Size.Magnitude < 160
			and not isChar(x)
			and allowed(x)
	end
	local function isWin(x)
		local n = x.Name:lower()
		return x.Material == Enum.Material.Glass
			or n:find("window") ~= nil
			or n:find("glass") ~= nil
			or (x.Transparency > 0.2 and x.Transparency < 1)
	end
	local function snd(id, parent, vol, pitch)
		local s = Instance.new("Sound")
		s.SoundId = id
		s.Volume = vol or 1
		s.PlaybackSpeed = pitch or 1
		s.RollOffMaxDistance = 250
		s.Parent = parent
		s:Play()
		D:AddItem(s, 6)
	end
	-- Roblox-style speech bubble (legacy chat games get the real Chat bubble)
	local okL, legacy = pcall(function()
		return game:GetService("TextChatService").ChatVersion == Enum.ChatVersion.LegacyChatService
	end)
	legacy = okL and legacy
	local bubbles = Instance.new("BillboardGui")
	bubbles.Name = "UF_Bubbles"
	bubbles.Size = UDim2.fromOffset(420, 220)
	bubbles.SizeOffset = Vector2.new(0, 0.5)
	bubbles.StudsOffset = Vector3.new(0, 1.6, 0)
	bubbles.MaxDistance = 120
	bubbles.LightInfluence = 0
	bubbles.Adornee = head
	bubbles.Parent = head
	local bl = Instance.new("UIListLayout")
	bl.VerticalAlignment = Enum.VerticalAlignment.Bottom
	bl.HorizontalAlignment = Enum.HorizontalAlignment.Center
	bl.SortOrder = Enum.SortOrder.LayoutOrder
	bl.Padding = UDim.new(0, 8)
	bl.Parent = bubbles
	local bn = 0
	local function bubble(txt)
		if legacy then
			pcall(function()
				game:GetService("Chat"):Chat(head, txt, Enum.ChatColor.White)
			end)
			return
		end
		bn += 1
		for _, c in ipairs(bubbles:GetChildren()) do
			if c:IsA("Frame") then
				local tl = c:FindFirstChild("Tail")
				if tl then
					tl:Destroy()
				end
				if c.LayoutOrder <= bn - 3 then
					c:Destroy()
				end
			end
		end
		local f = Instance.new("Frame")
		f.Name = "Bubble"
		f.LayoutOrder = bn
		f.BackgroundColor3 = Color3.new(1, 1, 1)
		f.BorderSizePixel = 0
		f.AutomaticSize = Enum.AutomaticSize.XY
		f.Size = UDim2.fromOffset(0, 0)
		local cr = Instance.new("UICorner")
		cr.CornerRadius = UDim.new(0, 12)
		cr.Parent = f
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.AutomaticSize = Enum.AutomaticSize.XY
		t.Size = UDim2.fromOffset(0, 0)
		t.Font = Enum.Font.GothamMedium
		t.TextSize = 18
		t.TextColor3 = Color3.fromRGB(57, 59, 61)
		t.Text = txt
		t.Parent = f
		local pd = Instance.new("UIPadding")
		pd.PaddingLeft = UDim.new(0, 12)
		pd.PaddingRight = UDim.new(0, 12)
		pd.PaddingTop = UDim.new(0, 8)
		pd.PaddingBottom = UDim.new(0, 8)
		pd.Parent = t
		local tl = Instance.new("Frame")
		tl.Name = "Tail"
		tl.AnchorPoint = Vector2.new(0.5, 0.5)
		tl.Position = UDim2.fromScale(0.5, 1)
		tl.Size = UDim2.fromOffset(12, 12)
		tl.Rotation = 45
		tl.BackgroundColor3 = Color3.new(1, 1, 1)
		tl.BorderSizePixel = 0
		tl.Parent = f
		f.Parent = bubbles
		D:AddItem(f, 5)
	end
	-- floating LET ME IN text above its head
	local function say(txt, n, big)
		for i = 1, n or 1 do
			local b = Instance.new("BillboardGui")
			b.Size = UDim2.fromOffset(big and 420 or 260, big and 90 or 50)
			b.StudsOffset = Vector3.new(math.random(-40, 40) / 10, 2.5 + math.random(0, 40) / 10, 0)
			b.AlwaysOnTop = true
			b.MaxDistance = 250
			b.LightInfluence = 0
			local t = Instance.new("TextLabel")
			t.Size = UDim2.fromScale(1, 1)
			t.BackgroundTransparency = 1
			t.Text = txt
			t.TextScaled = true
			t.Font = Enum.Font.Creepster
			t.TextColor3 = Color3.fromRGB(255, math.random(0, 40), math.random(0, 40))
			t.TextStrokeTransparency = 0
			t.Rotation = math.random(-15, 15)
			t.Parent = b
			b.Adornee = head
			b.Parent = head
			D:AddItem(b, 0.6 + math.random() * 0.8)
		end
		bubble(txt)
	end
	-- LET ME IN spam on a player's screen
	local function scream(plr, dur)
		if not SCREEN_EFFECTS then
			return
		end
		local pg = plr and plr:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		local g = Instance.new("ScreenGui")
		g.Name = "UF_LETMEIN"
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 999
		local f = Instance.new("Frame")
		f.Size = UDim2.fromScale(1, 1)
		f.BackgroundColor3 = Color3.new(1, 0, 0)
		f.BackgroundTransparency = 0.85
		f.BorderSizePixel = 0
		f.Parent = g
		g.Parent = pg
		D:AddItem(g, dur + 0.5)
		task.spawn(function()
			local e = os.clock() + dur
			while os.clock() < e and g.Parent do
				local t = Instance.new("TextLabel")
				t.BackgroundTransparency = 1
				t.Text = MSG
				t.Font = Enum.Font.Creepster
				t.TextScaled = true
				t.TextColor3 = Color3.fromRGB(math.random(180, 255), 0, 0)
				t.TextStrokeTransparency = 0.2
				t.Size = UDim2.fromScale(math.random(15, 45) / 100, math.random(6, 14) / 100)
				t.Position = UDim2.fromScale(math.random(0, 85) / 100, math.random(0, 90) / 100)
				t.Rotation = math.random(-25, 25)
				t.Parent = g
				D:AddItem(t, 0.4 + math.random() * 0.6)
				f.BackgroundTransparency = f.BackgroundTransparency > 0.8 and 0.65 or 0.85
				task.wait(0.07)
			end
		end)
	end
	local function screamAll(pos, r, plr, dur)
		local done = {}
		for _, p in ipairs(near(pos, r)) do
			done[p] = true
			scream(p, dur)
		end
		if plr and not done[plr] then
			scream(plr, dur)
		end
	end
	-- red sky for a moment
	local skyBusy = false
	local function redSky(dur)
		if not LIGHTING_EFFECTS then
			return
		end
		if skyBusy then
			return
		end
		skyBusy = true
		local cc = Instance.new("ColorCorrectionEffect")
		cc.TintColor = Color3.fromRGB(255, 40, 40)
		cc.Saturation = 0.4
		cc.Contrast = 0.3
		cc.Parent = L
		local oA, oO, oF = L.Ambient, L.OutdoorAmbient, L.FogColor
		L.Ambient = Color3.fromRGB(120, 0, 0)
		L.OutdoorAmbient = Color3.fromRGB(160, 0, 0)
		L.FogColor = Color3.fromRGB(120, 0, 0)
		local atm = L:FindFirstChildOfClass("Atmosphere")
		local made = atm == nil
		local oc, od, oh, ods
		if made then
			atm = Instance.new("Atmosphere")
			atm.Density = 0.35
			atm.Parent = L
		else
			oc, od, oh, ods = atm.Color, atm.Decay, atm.Haze, atm.Density
		end
		atm.Color = Color3.fromRGB(255, 0, 0)
		atm.Decay = Color3.fromRGB(120, 0, 0)
		atm.Haze = 2.5
		task.delay(dur, function()
			L.Ambient, L.OutdoorAmbient, L.FogColor = oA, oO, oF
			if made then
				atm:Destroy()
			else
				atm.Color, atm.Decay, atm.Haze, atm.Density = oc, od, oh, ods
			end
			local tw =
				TS:Create(cc, TweenInfo.new(0.4), { TintColor = Color3.new(1, 1, 1), Saturation = 0, Contrast = 0 })
			tw:Play()
			tw.Completed:Wait()
			cc:Destroy()
			skyBusy = false
		end)
	end
	-- light flicker
	local function flicker(pos, r)
		if not LIGHTING_EFFECTS then
			return
		end
		local ls = {}
		for _, v in ipairs(workspace:GetDescendants()) do
			if v:IsA("Light") and v.Parent ~= head then
				local pp = v.Parent
				local p = pp:IsA("BasePart") and pp.Position or pp:IsA("Attachment") and pp.WorldPosition
				if p and (p - pos).Magnitude < r then
					table.insert(ls, { v, v.Enabled })
				end
			end
		end
		task.spawn(function()
			for i = 1, 10 do
				for _, x in ipairs(ls) do
					if x[1].Parent then
						x[1].Enabled = not x[1].Enabled
					end
				end
				task.wait(math.random(3, 12) / 100)
			end
			for _, x in ipairs(ls) do
				if x[1].Parent then
					x[1].Enabled = x[2]
				end
			end
		end)
	end
	-- destruction
	local function shatter(x, dir)
		local cf, s = x.CFrame, x.Size
		local th = math.clamp(math.min(s.X, s.Y, s.Z), 0.05, 0.4)
		for i = 1, math.clamp(math.floor(s.X * s.Y / 2), 8, 30) do
			local sh = Instance.new("Part")
			sh.Name = "UF_Shard"
			sh.Size = Vector3.new(math.random(2, 12) / 10, math.random(2, 12) / 10, th)
			sh.CFrame = cf
				* CFrame.new((math.random() - 0.5) * s.X, (math.random() - 0.5) * s.Y, (math.random() - 0.5) * s.Z)
				* CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6)
			sh.Material = x.Material
			sh.Color = x.Color
			sh.Transparency = x.Transparency
			sh.Reflectance = x.Reflectance
			sh.Parent = workspace
			sh.AssemblyLinearVelocity = dir * math.random(25, 55)
				+ Vector3.new(math.random(-15, 15), math.random(5, 20), math.random(-15, 15))
			sh.AssemblyAngularVelocity = Vector3.new(math.random(-20, 20), math.random(-20, 20), math.random(-20, 20))
			D:AddItem(sh, 8)
		end
		x:Destroy()
	end
	local function loosen(x, pos, dir)
		for _, j in ipairs(x:GetJoints()) do
			j:Destroy()
		end
		x.Anchored = false
		x.AssemblyLinearVelocity = (x.Position - pos + Vector3.new(0, 0.01, 0)).Unit * math.random(10, 35)
			+ dir * 20
			+ Vector3.new(0, math.random(5, 25), 0)
		x.AssemblyAngularVelocity = Vector3.new(math.random(-6, 6), math.random(-6, 6), math.random(-6, 6))
	end
	local function collapse(pos, r, dir)
		local op = OverlapParams.new()
		op.FilterType = Enum.RaycastFilterType.Exclude
		op.FilterDescendantsInstances = params().FilterDescendantsInstances
		local n = 0
		local floorY = root.Position.Y - 2.2
		for _, x in ipairs(workspace:GetPartBoundsInRadius(pos, r, op)) do
			if n >= 80 then
				break
			end
			if x.Name ~= "UF_Shard" and breakable(x) and x.Position.Y + x.Size.Y / 2 > floorY then
				n += 1
				if isWin(x) then
					shatter(x, dir)
				else
					loosen(x, pos, dir)
				end
			end
		end
	end
	-- the thing in the way between it and the target (checks feet / chest / head height)
	local function obstacle(tp)
		local rp = params()
		local best, bd = nil, 1e9
		for _, h in ipairs({ -1, 0.8, 2 }) do
			local o = root.Position + Vector3.new(0, h, 0)
			local d = Vector3.new(tp.X, o.Y, tp.Z) - o
			if d.Magnitude > 0.1 then
				local r = workspace:Raycast(o, d.Unit * math.min(d.Magnitude, 40), rp)
				if r and breakable(r.Instance) and (r.Position - o).Magnitude < bd then
					best, bd = r, (r.Position - o).Magnitude
				end
			end
		end
		return best
	end
	-- procedural pose layer (on top of the walk/run/idle animations)
	local J = {}
	for _, n in ipairs({ "Neck", "RootJoint", "Right Shoulder", "Left Shoulder", "Right Hip", "Left Hip" }) do
		local m = rig:FindFirstChild(n, true)
		if m and m:IsA("Motor6D") then
			J[n] = { m = m, c0 = m.C0, cur = CFrame.identity, last = CFrame.identity }
		end
	end
	local mode = "idle"
	local twitch, twT = CFrame.identity, 0
	-- R6 joint axes: Right Shoulder +X out / +Z forward, Left Shoulder -X out / -Z forward, Neck & RootJoint +X = bend forward
	local function arms(fr, fl, out)
		return { ["Right Shoulder"] = ang(-(out or 0), 0, fr), ["Left Shoulder"] = ang(-(out or 0), 0, -fl) }
	end
	local function pose(t)
		local p = {}
		if mode == "bang" then
			local s1, s2 = math.abs(math.sin(t * 12)), math.abs(math.sin(t * 12 + 1.6))
			p = arms(95 + s1 * 45, 95 + s2 * 45)
			p.RootJoint = ang(8 + s1 * 5, 0, 0)
			p.Neck = ang(10 + math.random(-6, 6), 0, math.random(-8, 8))
		elseif mode == "scream" then
			local j = math.random(-10, 10)
			p = arms(20, 20, 75 + j)
			p.Neck = ang(-40 + j, 0, j)
			p.RootJoint = ang(-8, 0, 0)
		elseif mode == "reach" then
			local w = math.sin(t * 6) * 12
			p = arms(85 + w, 85 - w)
			p.RootJoint = ang(8, 0, 0)
			p.Neck = ang(8, 0, math.sin(t * 3) * 15)
		elseif mode == "chase" then
			p.Neck = ang(10, 0, 0)
			p.RootJoint = ang(6, 0, 0)
		elseif mode == "lift" then
			local j = math.random(-5, 5)
			p = arms(150 + j, 150 - j)
			p.Neck = ang(-20, 0, 0)
			p.RootJoint = ang(-6, 0, 0)
		elseif mode == "rip" then
			local j = math.sin(t * 30) * 25
			p = arms(150 + j, 150 - j, 20 + math.abs(j))
			p.Neck = ang(-15 + math.random(-8, 8), 0, math.random(-10, 10))
			p.RootJoint = ang(-8, 0, 0)
		elseif mode == "slam" then
			p = arms(40, 40)
			p.RootJoint = ang(25, 0, 0)
			p.Neck = ang(20, 0, 0)
		elseif mode == "climb" then
			local s = math.sin(t * 10) * 30
			p = arms(160 + s, 160 - s)
			p["Right Hip"] = ang(0, 0, -s)
			p["Left Hip"] = ang(0, 0, -s)
			p.Neck = ang(-30, 0, math.sin(t * 4) * 10)
		elseif mode == "ceiling" then
			local s = math.sin(t * 9) * 25
			p = arms(90 + s, 90 - s)
			p["Right Hip"] = ang(0, 0, 90 - s)
			p["Left Hip"] = ang(0, 0, -90 - s)
			p.Neck = ang(math.random(-6, 6), 0, 180 + math.sin(t * 2) * 25)
		end
		if twT > t then
			p.Neck = (p.Neck or CFrame.identity) * twitch
		end
		return p
	end
	-- spawn
	local spawnCF = CFrame.new(0, 10, 0)
	local sl = workspace:FindFirstChildWhichIsA("SpawnLocation", true)
	if sl then
		spawnCF = sl.CFrame + Vector3.new(0, 4, 0)
	end
	local ps = P:GetPlayers()
	local sc = #ps > 0 and ps[math.random(#ps)].Character
	if SPAWN_AT then
		spawnCF = SPAWN_AT
	elseif alive(sc) then
		local tr = sc.HumanoidRootPart
		local back = -tr.CFrame.LookVector
		local r = workspace:Raycast(tr.Position, back * 35, params())
		local pos = r and r.Position - back * 2 or tr.Position + back * 35
		local g = workspace:Raycast(pos + Vector3.new(0, 3, 0), Vector3.new(0, -60, 0), params())
		if g then
			pos = g.Position + Vector3.new(0, 3.2, 0)
		end
		spawnCF = CFrame.lookAt(pos, Vector3.new(tr.Position.X, pos.Y, tr.Position.Z))
	end
	rig:PivotTo(spawnCF)
	rig.Parent = workspace
	pcall(function()
		root:SetNetworkOwner(nil)
	end)
	-- animations (Roblox-owned R6 animations, usable in any game)
	local T = {}
	for k, id in pairs({ idle = 180435571, walk = 180426354, run = 180426354 }) do
		local a = Instance.new("Animation")
		a.AnimationId = "rbxassetid://" .. id
		local ok, tr = pcall(function()
			return animator:LoadAnimation(a)
		end)
		if ok and tr then
			T[k] = tr
		end
	end
	local curAnim
	local function play(n, v)
		local tr = T[n]
		if not tr then
			return
		end
		if curAnim ~= n then
			for k, o in pairs(T) do
				if k ~= n and o.IsPlaying then
					o:Stop(0.25)
				end
			end
			tr:Play(0.25)
			curAnim = n
		end
		if n ~= "idle" then
			tr:AdjustSpeed(math.clamp(v / 16, 0.6, 2))
		end
	end
	local t0 = os.clock()
	local hb
	hb = RunS.Heartbeat:Connect(function(dt)
		if not rig.Parent then
			hb:Disconnect()
			return
		end
		local t = os.clock() - t0
		if math.random() < dt * 0.4 then
			twitch = ang(math.random(-35, 35), math.random(-50, 50), math.random(-30, 30))
			twT = t + 0.12
		end
		local p = pose(t)
		local a = 1 - math.exp(-dt * 14)
		for n, j in pairs(J) do
			if j.m.Parent then
				j.cur = j.cur:Lerp(p[n] or CFrame.identity, a)
				local _, d = (j.cur:Inverse() * j.last):ToAxisAngle()
				if d > 0.003 then
					j.m.C0 = j.c0 * j.cur
					j.last = j.cur
				end
			end
		end
		local v = (root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude
		if mode == "down" or dead or crawling then
			for _, o in pairs(T) do
				if o.IsPlaying then
					o:Stop(0.1)
				end
			end
			curAnim = nil
			return
		end
		play(
			(mode == "bang" or mode == "scream" or mode == "lift" or mode == "rip" or mode == "slam") and "idle"
				or (v > 1 and (hum.WalkSpeed >= 20 and "run" or "walk") or "idle"),
			v
		)
	end)
	-- abilities
	local function vis(on)
		for _, x in ipairs(rig:GetDescendants()) do
			if x:IsA("BasePart") and x ~= root and x.Name ~= "UF_Col" or x:IsA("Decal") then
				x.Transparency = on and 0 or 1
			end
		end
	end
	local function blink(cf)
		for i = 1, 3 do
			vis(false)
			task.wait(0.05)
			vis(true)
			task.wait(0.05)
		end
		vis(false)
		say(MSG, 3)
		rig:PivotTo(cf)
		root.AssemblyLinearVelocity = Vector3.zero
		task.wait(0.1)
		for i = 1, 3 do
			vis(true)
			task.wait(0.04)
			vis(false)
			task.wait(0.04)
		end
		vis(true)
	end
	local function behind(tr, d)
		local back = -tr.CFrame.LookVector
		local r = workspace:Raycast(tr.Position, back * d, params())
		local p = r and r.Position - back * 1.5 or tr.Position + back * d
		return CFrame.lookAt(p, Vector3.new(tr.Position.X, p.Y, tr.Position.Z))
	end
	local busy, breaching = false, false
	local function moveTo(pos, timeout)
		if busy then
			return false
		end
		hum:MoveTo(pos)
		local e = os.clock() + (timeout or 1)
		local f = Vector3.new(1, 0, 1)
		while os.clock() < e and rig.Parent and not busy do
			if (root.Position * f - pos * f).Magnitude < 2.5 then
				return true
			end
			task.wait()
		end
		return false
	end
	local rage, begs = 0, 0
	local function breach(x, pos, plr)
		if not x.Parent then
			return
		end
		hum:MoveTo(root.Position)
		root.CFrame = CFrame.lookAt(root.Position, Vector3.new(pos.X, root.Position.Y, pos.Z))
		breaching = true
		mode = "bang"
		screamAll(pos, 90, plr, 3.2)
		flicker(pos, 60)
		local e = os.clock() + 3
		local ocf, shake = x.CFrame, x.Anchored and #x:GetJoints() == 0
		while os.clock() < e and x.Parent and rig.Parent and not downed do
			say(MSG, math.random(2, 4), math.random() < 0.3)
			snd("rbxasset://sounds/collide.wav", x, 3, math.random(5, 9) / 10)
			if shake then
				x.CFrame = ocf * CFrame.new(
					math.random(-10, 10) / 60,
					math.random(-10, 10) / 60,
					math.random(-10, 10) / 60
				)
			end
			task.wait(0.18)
		end
		if x.Parent and shake then
			x.CFrame = ocf
		end
		if not rig.Parent or downed then
			breaching = false
			return
		end
		mode = "scream"
		say(MSG, 8, true)
		redSky(1)
		local dir = Vector3.new(pos.X - root.Position.X, 0, pos.Z - root.Position.Z)
		dir = dir.Magnitude > 0.01 and dir.Unit or root.CFrame.LookVector
		local ex = Instance.new("Explosion")
		ex.Position = pos
		ex.BlastRadius = 4
		ex.BlastPressure = 0
		ex.DestroyJointRadiusPercent = 0
		ex.ExplosionType = Enum.ExplosionType.NoCraters
		ex.Parent = workspace
		snd("rbxasset://sounds/glassbreak.wav", root, 3, 1)
		if x.Parent then
			if isWin(x) then
				shatter(x, dir)
			else
				loosen(x, pos, dir)
			end
		end
		collapse(pos, 14, dir)
		rage += 1
		hum.WalkSpeed = math.min(16 + rage * 2 + (phase - 1) * 3, 30)
		task.wait(0.8)
		mode = "chase"
		breaching = false
	end
	local function beg(plr)
		mode = "reach"
		screamAll(root.Position, 120, plr, 2.5)
		flicker(root.Position, 80)
		local e = os.clock() + 2.5
		while os.clock() < e and rig.Parent do
			say(MSG, math.random(2, 5), math.random() < 0.4)
			task.wait(0.12)
		end
		if math.random() < 0.5 then
			redSky(1)
		end
	end
	local function jumpscare(plr)
		if not SCREEN_EFFECTS then
			return
		end
		local pg = plr:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		local g = Instance.new("ScreenGui")
		g.Name = "UF_Scare"
		g.IgnoreGuiInset = true
		g.ResetOnSpawn = false
		g.DisplayOrder = 1000
		local f = Instance.new("Frame")
		f.Size = UDim2.fromScale(1, 1)
		f.BackgroundColor3 = Color3.new(0, 0, 0)
		f.BorderSizePixel = 0
		f.Parent = g
		local t = Instance.new("TextLabel")
		t.AnchorPoint = Vector2.new(0.5, 0.5)
		t.Position = UDim2.fromScale(0.5, 0.5)
		t.Size = UDim2.fromScale(0.3, 0.15)
		t.BackgroundTransparency = 1
		t.Text = MSG
		t.TextScaled = true
		t.Font = Enum.Font.Creepster
		t.TextColor3 = Color3.new(1, 0, 0)
		t.TextStrokeTransparency = 0
		t.Parent = f
		g.Parent = pg
		TS:Create(t, TweenInfo.new(0.35, Enum.EasingStyle.Back), { Size = UDim2.fromScale(1.1, 0.6) }):Play()
		task.spawn(function()
			for i = 1, 12 do
				f.BackgroundColor3 = i % 2 == 0 and Color3.new(0, 0, 0) or Color3.fromRGB(90, 0, 0)
				t.Rotation = math.random(-8, 8)
				task.wait(0.08)
			end
		end)
		D:AddItem(g, 1.8)
	end
	-- wall climbing + ceiling crawling (anchored and moved along surfaces with raycasts)
	local climbCD = 0
	local function upright(pos, look)
		look = Vector3.new(look.X, 0, look.Z)
		if look.Magnitude < 0.05 then
			look = Vector3.new(0, 0, -1)
		end
		return CFrame.lookAt(pos, pos + look.Unit)
	end
	local function wallNear(pref)
		local rp = params()
		local dirs = { pref }
		local best
		for i = 0, 7 do
			local a = i * math.pi / 4
			table.insert(dirs, Vector3.new(math.cos(a), 0, math.sin(a)))
		end
		for k, d in ipairs(dirs) do
			if d.Magnitude > 0.01 then
				local r = workspace:Raycast(root.Position, d.Unit * 12, rp)
				if r and math.abs(r.Normal.Y) < 0.3 then
					if k == 1 then
						return r
					end
					if
						not best or (r.Position - root.Position).Magnitude < (best.Position - root.Position).Magnitude
					then
						best = r
					end
				end
			end
		end
		return best
	end
	local function ceilingAbove()
		local r = workspace:Raycast(root.Position, Vector3.new(0, 30, 0), params())
		return r and r.Normal.Y < -0.5 and r.Position.Y - root.Position.Y > 6
	end
	local function climb(w, plr)
		climbCD = os.clock() + 6
		if (w.Position - root.Position).Magnitude > 3 then
			moveTo(w.Position + w.Normal * 1.5, 2)
		end
		if busy or downed or dead then
			return
		end
		busy = true
		crawling = true
		mode = "climb"
		root.Anchored = true
		local rp = params()
		local n = Vector3.new(w.Normal.X, 0, w.Normal.Z).Unit
		local pos = Vector3.new(w.Position.X, root.Position.Y, w.Position.Z) + n * 1.2
		local e = os.clock() + 12
		local result, ceil = "fail", nil
		bubble("hehe...")
		while rig.Parent and not downed and os.clock() < e do
			local dt = RunS.Heartbeat:Wait()
			root.CFrame = CFrame.lookAt(pos, pos - n)
			local up = workspace:Raycast(pos, Vector3.new(0, 3.5, 0), rp)
			if up then
				result, ceil = "ceiling", up
				break
			end
			if not workspace:Raycast(pos + Vector3.new(0, 2, 0), -n * 3, rp) then
				result = "top"
				break
			end
			pos += Vector3.new(0, dt * (10 + phase * 2), 0)
			if math.random() < dt * 0.6 then
				snd("rbxasset://sounds/collide.wav", root, 1, math.random(14, 20) / 10)
			end
		end
		if downed then
			return
		end
		local look = -n
		if result == "top" then
			local g = workspace:Raycast(pos + Vector3.new(0, 5, 0) - n * 2, Vector3.new(0, -10, 0), rp)
			if g then
				pos = g.Position + Vector3.new(0, 3, 0)
			end
		elseif result == "ceiling" then
			mode = "ceiling"
			bubble("i see you.")
			local cpos = Vector3.new(pos.X, ceil.Position.Y - 2.5, pos.Z) + n * 2
			local e2 = os.clock() + 20
			local said = os.clock()
			while rig.Parent and not downed and os.clock() < e2 do
				local dt = RunS.Heartbeat:Wait()
				local c = plr.Character
				if not alive(c) then
					break
				end
				local tr = c.HumanoidRootPart
				local flat = Vector3.new(tr.Position.X - cpos.X, 0, tr.Position.Z - cpos.Z)
				if flat.Magnitude < 3 then
					break
				end
				local h = flat.Unit
				look = h
				if workspace:Raycast(cpos, h * 2.5, rp) then
					break
				end
				local nxt = cpos + h * dt * (14 + phase * 2)
				local u = workspace:Raycast(nxt, Vector3.new(0, 4, 0), rp)
				if not u then
					break
				end
				cpos = Vector3.new(nxt.X, u.Position.Y - 2.5, nxt.Z)
				root.CFrame = CFrame.fromMatrix(cpos, h:Cross(Vector3.new(0, -1, 0)), h, Vector3.new(0, -1, 0))
				if os.clock() - said > 2.5 then
					said = os.clock()
					bubble(math.random() < 0.5 and "LET ME IN" or "look up.")
				end
			end
			pos = cpos
		end
		if downed then
			return
		end
		root.CFrame = upright(pos, look)
		root.Anchored = false
		root.AssemblyLinearVelocity = Vector3.new(0, -30, 0)
		crawling = false
		mode = "chase"
		busy = false
	end
	-- phases: dies -> ragdolls -> gets back up and talks (speech bubbles only). Phase 3+ fakes losing its Humanoid (studs).
	local DIALOG = {
		{ "...that hurt.", "you can't keep me out.", "i'm still here.", "LET ME IN" },
		{
			"i counted every brick in your walls.",
			"i know which window is yours.",
			"you locked the door. i heard it click.",
			"LET ME IN",
		},
		{
			"did you think i was just a model?",
			"no humanoid. no name. just bricks.",
			"...",
			"NOPE.",
			"i'm still outside. LET. ME. IN.",
		},
	}
	local FINAL = { "no...", "this isn't over.", "i'll be at your window tonight.", "let me in..." }
	local function talk(lines)
		for _, l in ipairs(lines) do
			if not rig.Parent then
				return
			end
			bubble(l)
			task.wait(1.3 + #l * 0.04)
		end
	end
	local rag = {}
	local function ragdoll(on)
		for _, o in ipairs(rag) do
			o:Destroy()
		end
		rag = {}
		for _, m in ipairs(rig:GetDescendants()) do
			if m:IsA("Motor6D") and m.Name ~= "RootJoint" and m.Part0 and m.Part1 then
				m.Enabled = not on
				if on then
					local a0 = Instance.new("Attachment")
					a0.CFrame = m.C0
					a0.Parent = m.Part0
					local a1 = Instance.new("Attachment")
					a1.CFrame = m.C1
					a1.Parent = m.Part1
					local b = Instance.new("BallSocketConstraint")
					b.Attachment0 = a0
					b.Attachment1 = a1
					b.LimitsEnabled = true
					b.UpperAngle = 70
					b.TwistLimitsEnabled = true
					b.TwistLowerAngle = -45
					b.TwistUpperAngle = 45
					b.Parent = m.Part1
					local cp = Instance.new("Part")
					cp.Name = "UF_Col"
					cp.Size = m.Part1.Size * 0.7
					cp.Transparency = 1
					cp.Massless = true
					cp.CanCollide = true
					cp.CFrame = m.Part1.CFrame
					cp.Parent = rig
					local w = Instance.new("WeldConstraint")
					w.Part0 = m.Part1
					w.Part1 = cp
					w.Parent = cp
					table.insert(rag, a0)
					table.insert(rag, a1)
					table.insert(rag, b)
					table.insert(rag, cp)
				end
			end
		end
		hum.PlatformStand = on
		if on then
			hum:ChangeState(Enum.HumanoidStateType.Physics)
		end
	end
	local function studs(on)
		local st = on and Enum.SurfaceType.Studs or Enum.SurfaceType.Smooth
		for _, x in ipairs(rig:GetChildren()) do
			if x:IsA("BasePart") and x ~= root and x.Name ~= "UF_Col" then
				x.Material = Enum.Material.Plastic
				x.TopSurface = st
				x.BottomSurface = st
				x.FrontSurface = st
				x.BackSurface = st
				x.LeftSurface = st
				x.RightSurface = st
			end
		end
		hum.DisplayDistanceType = on and Enum.HumanoidDisplayDistanceType.None
			or Enum.HumanoidDisplayDistanceType.Viewer
		glow.Enabled = not on
	end
	down = function()
		if downed or dead or not rig.Parent then
			return
		end
		crawling = false
		root.Anchored = false
		downed = true
		busy = true
		mode = "down"
		hum.Health = 1
		hum:MoveTo(root.Position)
		for _, o in pairs(T) do
			o:Stop(0.1)
		end
		curAnim = nil
		ragdoll(true)
		root.AssemblyLinearVelocity = -root.CFrame.LookVector * 25 + Vector3.new(0, 15, 0)
		root.AssemblyAngularVelocity = Vector3.new(math.random(-8, 8), 0, math.random(-8, 8))
		snd("rbxasset://sounds/collide.wav", root, 4, 0.5)
		task.wait(1.5)
		if phase >= 3 then
			studs(true)
		end
		if phase >= 4 then
			dead = true
			hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
			hum.Health = 0
			talk(FINAL)
			task.wait(4)
			rig:Destroy()
			return
		end
		task.wait(phase >= 3 and 5 or 2.5)
		for i = 1, 8 do
			for _, x in ipairs(rig:GetChildren()) do
				if x:IsA("BasePart") and x ~= root and x.Name ~= "UF_Col" then
					x.AssemblyAngularVelocity =
						Vector3.new(math.random(-15, 15), math.random(-15, 15), math.random(-15, 15))
				end
			end
			task.wait(0.12)
		end
		if phase >= 3 then
			studs(false)
		end
		ragdoll(false)
		local pos = root.Position
		local lk = root.CFrame.LookVector
		lk = Vector3.new(lk.X, 0, lk.Z)
		if lk.Magnitude < 0.1 then
			lk = Vector3.new(0, 0, -1)
		end
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
		rig:PivotTo(CFrame.lookAt(pos + Vector3.new(0, 2.5, 0), pos + Vector3.new(0, 2.5, 0) + lk.Unit))
		hum:ChangeState(Enum.HumanoidStateType.GettingUp)
		phase += 1
		hum.MaxHealth = 1000 + (phase - 1) * 500
		hum.Health = hum.MaxHealth
		glow.Brightness = 2 + phase
		hum.WalkSpeed = 16 + (phase - 1) * 3
		mode = "scream"
		task.wait(0.6)
		mode = "idle"
		talk(DIALOG[phase - 1])
		mode = "chase"
		downed = false
		busy = false
	end
	hum.HealthChanged:Connect(function(h)
		if h <= 1 and not downed and not killing and not dead then
			task.spawn(down)
		end
	end)
	-- kill: pick the player up, rip their limbs off, toss them underground
	local function killSeq(plr)
		local c = plr.Character
		local h = alive(c)
		if not h then
			return
		end
		busy = true
		killing = true
		local tr = c.HumanoidRootPart
		local hold, lift = true, 1
		local ok = pcall(function()
			hum:MoveTo(root.Position)
			root.CFrame = CFrame.lookAt(root.Position, Vector3.new(tr.Position.X, root.Position.Y, tr.Position.Z))
			jumpscare(plr)
			snd("rbxasset://sounds/collide.wav", root, 5, 0.4)
			h.PlatformStand = true
			tr.Anchored = true
			task.spawn(function()
				while hold and tr.Parent do
					tr.CFrame = root.CFrame
						* CFrame.new(math.random(-5, 5) / 50, lift, -2.6)
						* CFrame.Angles(0, math.pi, 0)
						* CFrame.Angles(math.rad(math.random(-8, 8)), 0, math.rad(math.random(-8, 8)))
					RunS.Heartbeat:Wait()
				end
			end)
			mode = "lift"
			say(MSG, 4, true)
			for i = 1, 20 do
				lift = 1 + i * 0.2
				task.wait(0.03)
			end
			task.wait(0.4)
			mode = "rip"
			local limbs = {}
			for i = 1, 4 do
				task.wait(0.55)
				snd("rbxasset://sounds/collide.wav", tr, 4, math.random(3, 6) / 10)
				say(MSG, 2)
			end
			task.wait(0.5)
			mode = "slam"
			say(MSG, 6, true)
			local g = workspace:Raycast(root.Position, Vector3.new(0, -20, 0), params())
			local gy = g and g.Position.Y or root.Position.Y - 3
			local fp = (root.CFrame * CFrame.new(0, 0, -5)).Position
			local hitPos = Vector3.new(fp.X, gy, fp.Z)
			hold = false
			RunS.Heartbeat:Wait()
			for _, x in ipairs(c:GetDescendants()) do
				if x:IsA("BasePart") then
					x.CanCollide = false
				end
			end
			for _, x in ipairs(limbs) do
				x.CanCollide = false
			end
			local tw = TS:Create(
				tr,
				TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
				{ CFrame = CFrame.new(fp.X, gy - 30, fp.Z) * CFrame.Angles(math.rad(90), 0, 0) }
			)
			tw:Play()
			task.wait(0.2)
			local ex = Instance.new("Explosion")
			ex.Position = hitPos
			ex.BlastRadius = 3
			ex.BlastPressure = 0
			ex.DestroyJointRadiusPercent = 0
			ex.ExplosionType = Enum.ExplosionType.NoCraters
			ex.Parent = workspace
			for i = 1, 12 do
				local d = Instance.new("Part")
				d.Size = Vector3.new(1, 1, 1) * math.random(4, 10) / 10
				d.Material = Enum.Material.Ground
				d.Color = Color3.fromRGB(86, 66, 54)
				d.CFrame = CFrame.new(hitPos + Vector3.new(0, 0.5, 0))
				d.Parent = workspace
				d.AssemblyLinearVelocity = Vector3.new(math.random(-20, 20), math.random(20, 40), math.random(-20, 20))
				D:AddItem(d, 4)
			end
			tw.Completed:Wait()
			h.Health = 0
		end)
		hold = false
		if not ok and h.Parent and h.Health > 0 then
			h.Health = 0
		end
		mode = "scream"
		say("I'M IN", 6, true)
		task.wait(1)
		mode = "chase"
		busy = false
		killing = false
		if hum.Health <= 1 then
			task.spawn(down)
		end
	end
	-- catch players
	task.spawn(function()
		local cd = {}
		while rig.Parent and not dead do
			for _, p in ipairs(P:GetPlayers()) do
				local h = alive(p.Character)
				if
					h
					and not busy
					and not breaching
					and (p.Character.HumanoidRootPart.Position - root.Position).Magnitude < 4
					and (cd[p] or 0) < os.clock()
				then
					cd[p] = os.clock() + 8
					if KILL then
						task.spawn(killSeq, p)
					else
						jumpscare(p)
						snd("rbxasset://sounds/collide.wav", root, 5, 0.4)
						task.spawn(function()
							mode = "scream"
							say("I'M IN", 6, true)
							task.wait(1)
							mode = "chase"
						end)
					end
				end
			end
			task.wait(0.1)
		end
	end)
	-- intro
	redSky(1)
	flicker(root.Position, 150)
	say(MSG, 6, true)
	for _, p in ipairs(P:GetPlayers()) do
		scream(p, 1.2)
	end
	-- brain
	task.spawn(function()
		while rig.Parent and not dead do
			if busy then
				task.wait(0.1)
				continue
			end
			local plr, dist = nearest()
			if not plr then
				mode = "idle"
				if math.random() < 0.2 then
					say("let me in...", 1)
				end
				task.wait(1)
			else
				local tr = plr.Character.HumanoidRootPart
				local hit = obstacle(tr.Position)
				if hit and isWin(hit.Instance) and (hit.Position - root.Position).Magnitude < 5.5 then
					breach(hit.Instance, hit.Position, plr)
				else
					local path =
						PFS:CreatePath({ AgentRadius = 2.2, AgentHeight = 5.5, AgentCanJump = true, WaypointSpacing = 4 })
					local ok = pcall(function()
						path:ComputeAsync(root.Position, tr.Position)
					end)
					local wps = ok and path.Status == Enum.PathStatus.Success and path:GetWaypoints() or nil
					local len = 0
					if wps then
						for i = 2, #wps do
							len += (wps[i].Position - wps[i - 1].Position).Magnitude
						end
					end
					if wps and not (hit and len > dist * 2.5) then
						begs = 0
						mode = dist < 25 and "reach" or "chase"
						hum.WalkSpeed = math.min(16 + rage * 2 + (phase - 1) * 3 + (dist < 40 and 6 or 0), 30)
						for i = 2, math.min(#wps, 7) do
							if wps[i].Action == Enum.PathWaypointAction.Jump then
								hum.Jump = true
							end
							if not moveTo(wps[i].Position, 1.2) then
								break
							end
							local h2 = obstacle(tr.Position)
							if h2 and isWin(h2.Instance) and (h2.Position - root.Position).Magnitude < 5.5 then
								break
							end
						end
						if
							dist > 15
							and dist < 70
							and os.clock() > climbCD
							and math.random() < 0.06
							and ceilingAbove()
						then
							local w = wallNear(
								Vector3.new(tr.Position.X - root.Position.X, 0, tr.Position.Z - root.Position.Z)
							)
							if w then
								climb(w, plr)
							end
						end
						if dist > 30 and math.random() < 0.05 then
							local d =
								Vector3.new(tr.Position.X - root.Position.X, 0, tr.Position.Z - root.Position.Z).Unit
							if not workspace:Raycast(root.Position, d * 14, params()) then
								local p = root.Position + d * 12
								blink(CFrame.lookAt(p, Vector3.new(tr.Position.X, p.Y, tr.Position.Z)))
							end
						end
					else
						mode = "reach"
						hum.WalkSpeed = math.min(18 + rage * 2 + (phase - 1) * 3, 34)
						if hit then
							if (hit.Position - root.Position).Magnitude > 5.5 then
								moveTo(hit.Position - (hit.Position - root.Position).Unit * 3, 2)
							end
							if hit.Instance.Parent and (hit.Position - root.Position).Magnitude < 12 then
								breach(hit.Instance, hit.Position, plr)
							end
						else
							local w = os.clock() > climbCD
								and wallNear(
									Vector3.new(tr.Position.X - root.Position.X, 0, tr.Position.Z - root.Position.Z)
								)
							if w then
								climb(w, plr)
							else
								moveTo(tr.Position, 1.5)
								begs += 1
								if begs % 3 == 0 then
									beg(plr)
								end
								if begs >= 9 and alive(plr.Character) then
									begs = 0
									blink(behind(plr.Character.HumanoidRootPart, 6))
								end
							end
						end
					end
				end
			end
			task.wait()
		end
	end)
end

-- Floating "LET ME IN" text coming out of the core
local function coreText(size)
	local gui = Instance.new("BillboardGui")
	gui.Size = UDim2.fromOffset(size, size / 4)
	gui.StudsOffset = Vector3.new(math.random(-60, 60) / 10, math.random(-20, 60) / 10, 0)
	gui.AlwaysOnTop = true
	gui.MaxDistance = 250
	gui.LightInfluence = 0
	local label = Instance.new("TextLabel")
	label.Size = UDim2.fromScale(1, 1)
	label.BackgroundTransparency = 1
	label.Text = "LET ME IN"
	label.TextScaled = true
	label.Font = Enum.Font.Creepster
	label.TextColor3 = Color3.fromRGB(255, math.random(0, 40), math.random(0, 40))
	label.TextStrokeTransparency = 0
	label.Rotation = math.random(-20, 20)
	label.Parent = gui
	gui.Adornee = core
	gui.Parent = core
	Debris:AddItem(gui, 0.5 + math.random() * 0.6)
end

local function summon(player)
	clicker:Destroy()

	local parts = {}
	for _, v in ipairs(model:GetDescendants()) do
		if v:IsA("BasePart") then
			table.insert(parts, v)
		end
	end

	local base = model:GetPivot()
	local size = model:GetExtentsSize()
	local rotation = base - base.Position

	-- Where User_F will stand: the ground under the model, facing whoever clicked
	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	rayParams.FilterDescendantsInstances = { model }
	local ground = workspace:Raycast(base.Position + Vector3.new(0, 5, 0), Vector3.new(0, -200, 0), rayParams)
	local spawnPos = (ground and ground.Position or base.Position) + Vector3.new(0, 3.2, 0)
	local lookAt = spawnPos + Vector3.new(0, 0, -1)
	local char = player and player.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if hrp then
		lookAt = Vector3.new(hrp.Position.X, spawnPos.Y, hrp.Position.Z)
	end

	-- Remember every part's place in the model so it can be spun/spread as one piece
	local offset, color, material, selfSpin = {}, {}, {}, {}
	for _, p in ipairs(parts) do
		p.Anchored = true
		p.CanCollide = false
		offset[p] = base:ToObjectSpace(p.CFrame)
		color[p], material[p] = p.Color, p.Material
		selfSpin[p] = Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10)) / 10
	end

	-- Core wakes up
	core.Material = Enum.Material.Neon
	core.Color = RED
	local light = Instance.new("PointLight")
	light.Color = RED
	light.Range = 4
	light.Brightness = 1
	light.Parent = core
	local sparks = Instance.new("ParticleEmitter")
	sparks.Color = ColorSequence.new(RED, Color3.fromRGB(30, 0, 0))
	sparks.LightEmission = 1
	sparks.Size = NumberSequence.new(0.6, 0)
	sparks.Speed = NumberRange.new(10, 30)
	sparks.SpreadAngle = Vector2.new(180, 180)
	sparks.Lifetime = NumberRange.new(0.4, 0.9)
	sparks.Rate = 0
	sparks.Parent = core
	local hum = Instance.new("Sound")
	hum.SoundId = "rbxasset://sounds/electronicpingshort.wav"
	hum.Looped = true
	hum.Volume = 2
	hum.PlaybackSpeed = 0.3
	hum.Parent = core
	hum:Play()

	-- Rumble -> rise -> spin faster and faster while the pieces drift apart
	local start = os.clock()
	local total = RISE_TIME + SPIN_TIME
	local nextText = 0
	local conn
	conn = RunService.Heartbeat:Connect(function()
		local t = os.clock() - start
		local k = math.clamp((t - RISE_TIME) / SPIN_TIME, 0, 1) -- 0 while rumbling, 0->1 while spinning
		local a = math.clamp(t / total, 0, 1)

		local rise = (k ^ 2) * (size.Y + 14)
		local spin = (k ^ 3) * 45
		local spread = 1 + k * 0.9
		local shake = 0.12 + a * 0.5
		local wobble = CFrame.Angles(math.sin(t * 7) * 0.25 * k, 0, math.cos(t * 5) * 0.25 * k)
		local pivot = CFrame.new(base.Position + Vector3.new(0, rise, 0))
			* CFrame.Angles(0, spin, 0)
			* wobble
			* rotation

		for _, p in ipairs(parts) do
			if p.Parent then
				local o = offset[p]
				local jitter = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5) * shake
				local tumble = CFrame.Angles(selfSpin[p].X * t * k, selfSpin[p].Y * t * k, selfSpin[p].Z * t * k)
				p.CFrame = pivot * CFrame.new(o.Position * spread + jitter) * (o - o.Position) * tumble
				if p ~= core then
					if math.random() < a * 0.35 then
						p.Material, p.Color = Enum.Material.Neon, RED
					else
						p.Material, p.Color = material[p], color[p]
					end
				end
			end
		end

		light.Range = 4 + a * 40
		light.Brightness = 1 + a * 8
		sparks.Rate = a * 400
		hum.PlaybackSpeed = 0.3 + a * 1.5
		if t > nextText then
			nextText = t + 0.25 - a * 0.2
			coreText(150 + a * 300)
		end
	end)

	task.wait(total)
	conn:Disconnect()

	-- Blinding flash
	for _, p in ipairs(parts) do
		if p.Parent then
			p.Material, p.Color = Enum.Material.Neon, Color3.new(1, 1, 1)
		end
	end
	light.Color = Color3.new(1, 1, 1)
	light.Brightness = 20
	task.wait(0.15)

	-- Explode: no damage, just a blast and flying debris
	local center = core.Position
	hum:Destroy()
	sparks.Rate = 0
	local boom = Instance.new("Explosion")
	boom.Position = center
	boom.BlastRadius = math.max(size.Magnitude / 2, 6)
	boom.BlastPressure = 0
	boom.DestroyJointRadiusPercent = 0
	boom.ExplosionType = Enum.ExplosionType.NoCraters
	boom.Parent = workspace

	local wave = Instance.new("Part")
	wave.Shape = Enum.PartType.Ball
	wave.Anchored = true
	wave.CanCollide = false
	wave.CanQuery = false
	wave.Material = Enum.Material.Neon
	wave.Color = RED
	wave.Size = Vector3.new(2, 2, 2)
	wave.Position = center
	wave.Parent = workspace
	TweenService
		:Create(wave, TweenInfo.new(0.6, Enum.EasingStyle.Quad), { Size = Vector3.new(70, 70, 70), Transparency = 1 })
		:Play()
	Debris:AddItem(wave, 0.7)

	for _, p in ipairs(parts) do
		if p.Parent then
			p.Material = material[p]
			p.Color = color[p]:Lerp(Color3.new(0, 0, 0), 0.6)
			p.Anchored = false
			p.CanCollide = true
			local dir = p.Position - center + Vector3.new(0, 0.01, 0)
			p.AssemblyLinearVelocity = dir.Unit * math.random(40, 90) + Vector3.new(0, math.random(20, 45), 0)
			p.AssemblyAngularVelocity = Vector3.new(math.random(-30, 30), math.random(-30, 30), math.random(-30, 30))
			Debris:AddItem(p, 10)
		end
	end

	spawnUserF(CFrame.lookAt(spawnPos, lookAt))
end

local used = false
clicker.MouseClick:Connect(function(player)
	if used then
		return
	end
	used = true
	summon(player)
end)
